-- Corrected compact historic import preserving CSV Ben/Louise net values exactly (v2 sign fix)
begin;


create temporary table tmp_historic_import (row_no int generated always as identity primary key,payment_date date not null,title text not null,amount numeric(12,2) not null,currency_code text not null,category_key text not null,source_type finance_app.payment_source_type not null,ben_contrib numeric(12,2) not null,lou_contrib numeric(12,2) not null,ben_split numeric(12,2) not null,lou_split numeric(12,2) not null) on commit drop;


do $$ begin if (select count(*) from finance_app.households)=0 then raise exception 'No household found. Run setup household SQL first.'; end if; if (select count(*) from finance_app.household_members where display_name in ('Ben Selby','Louise Billingham'))<2 then raise exception 'Ben/Louise household members not found. Ensure display names are set.'; end if; end $$;

create temporary table tmp_inserted (row_no int primary key,payment_id uuid not null,ben_user_id uuid not null,lou_user_id uuid not null,ben_contrib numeric(12,2) not null,lou_contrib numeric(12,2) not null,ben_split numeric(12,2) not null,lou_split numeric(12,2) not null) on commit drop;

with ctx as (select h.id as household_id from finance_app.households h order by h.created_at asc limit 1), users as (select (select user_id from finance_app.household_members where display_name='Ben Selby' limit 1) as ben_user_id,(select user_id from finance_app.household_members where display_name='Louise Billingham' limit 1) as lou_user_id), ins as (insert into finance_app.payments (household_id, title, amount, currency_code, fx_rate_to_gbp, fx_rate_date, amount_gbp, payment_date, category_key, notes, source_type, created_by) select ctx.household_id, t.title, t.amount, t.currency_code, 1, t.payment_date, t.amount, t.payment_date, t.category_key, null, t.source_type, users.ben_user_id from tmp_historic_import t cross join ctx cross join users returning id), numbered_ins as (select i.id, row_number() over(order by i.id) as rn from ins i), numbered_src as (select t.*, row_number() over(order by t.row_no) as rn from tmp_historic_import t) insert into tmp_inserted (row_no,payment_id,ben_user_id,lou_user_id,ben_contrib,lou_contrib,ben_split,lou_split) select s.row_no, i.id, u.ben_user_id, u.lou_user_id, s.ben_contrib, s.lou_contrib, s.ben_split, s.lou_split from numbered_src s join numbered_ins i on i.rn=s.rn cross join (select (select user_id from finance_app.household_members where display_name='Ben Selby' limit 1) as ben_user_id,(select user_id from finance_app.household_members where display_name='Louise Billingham' limit 1) as lou_user_id) u;


commit;
